use super::{reconciliation::*,admission_tests::{Fixture,evidence},authority::{Authority,Failure},authority_tests::{root,queued},lease_controller::{Controller,Pending,Owned,Validity},model::{self,Record},store::{nonce,Fault},effect_budget::{self,Kind,Phase}};
use crate::chat::Chat;
use std::{collections::BTreeMap,path::{Path,PathBuf},fs::{self,File,OpenOptions},os::fd::AsRawFd,sync::Arc};
pub(in crate::pet_runtime)fn inventory(path:&Path)->BTreeMap<PathBuf,String>{
    let mut files=BTreeMap::new();for p in fs::read_dir(path).unwrap(){let p=p.unwrap();if p.file_type().unwrap().is_dir(){files.extend(inventory(&p.path()));}else{files.insert(p.path(),model::hash(&fs::read(p.path()).unwrap()));}}files
}
fn shared(path:&Path)->File{let f=OpenOptions::new().read(true).write(true).open(path).unwrap();assert_eq!(unsafe{libc::flock(f.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);f}
fn setup(provider:&str)->(Fixture,Authority,Record,Pending,Owned,Chat){
    let f=Fixture::new();let a=Authority::ensure(&root(&f)).unwrap();let g=queued(&f,&f.goal(provider),&a);let main=Chat::persistent(f.path.join("live.json"));let c=Controller::new().unwrap();let pending=c.prepare(&g,&root(&f),&f.path.join("contexts"),&main,&evidence(&g,100_006),"native-claim".into(),100_006,Arc::new(|_,_,_|Validity::Current)).unwrap();let(r,o)=pending.claim(&f.store(),&a,&evidence(&g,100_007),100_007).unwrap();(f,a,r.record,pending,o.unwrap(),main)
}
fn read(f:&Fixture,g:&Record,now:u64)->Snapshot{f.store().reconciliation(&root(f),&g.id,&g.spec.owner.pet_id,&g.revision,now).unwrap()}
fn call(request:&str)->effect_budget::Attempt{effect_budget::Attempt{id:nonce().unwrap(),request_id:request.into(),input_hash:"a".repeat(64),kind:Kind::Model,output_reserved:2048,phase:Phase::Reserved,accepted_output:None,reserved_at:100_008,started_at:None,finished_at:None}}
#[test]fn draft_reconciliation_never_initializes_an_authority_or_any_receipt_directory(){
    let f=Fixture::new();let g=f.goal("ollama");let before=inventory(&f.path);let view=read(&f,&g,100_002);assert!(view.grant.is_none()&&view.attempts.is_empty());assert!(!view.execution_available&&!view.recovery_available&&!view.goal_complete);assert_eq!(inventory(&f.path),before);assert!(!root(&f).exists());
}
#[test]fn coherent_common_pet_inspection_coexists_with_real_shared_catalog_readers_without_writes(){
    for provider in ["codex","copilot","antigravity","ollama"]{
        let(f,_a,g,_p,o,_main)=setup(provider);let before=inventory(&f.path);let _goal=shared(&f.path.join("goals/.catalog.lock"));let _authority=shared(&root(&f).join(".catalog.lock"));let view=read(&f,&g,100_008);assert!(view.scan_complete&&view.source_consistent);assert!(!view.execution_available&&!view.recovery_available&&!view.criteria_verified&&!view.goal_complete);assert_eq!(view.grant.as_ref().unwrap().owner.state,super::runtime_owner::State::OriginalProcessLive);assert_eq!(view.grant.as_ref().unwrap().lease.as_ref(),Some(o.lease()));assert_eq!(view.accounting.as_ref().unwrap().unknown_attempts,0);assert_eq!(view.provider,provider);assert_eq!(inventory(&f.path),before);
    }
}
#[test]fn accounting_phase_or_settlement_alone_never_confirms_a_model_result_or_refunds_unknown_io(){
    for phase in [Phase::Reserved,Phase::Started,Phase::Uncertain,Phase::Settled]{
        let(f,a,g,_p,o,_main)=setup("ollama");let c=call("original-model");let row=&g.admissions[0];let proof=row.proof.as_ref().unwrap();a.reserve_attempt(&row.spec,proof,o.lease(),&c,100_009).unwrap();if phase!=Phase::Reserved{a.start_attempt(&row.spec,proof,o.lease(),&c,100_010).unwrap();}if matches!(phase,Phase::Uncertain|Phase::Settled){a.finish_attempt(&row.spec,proof,o.lease(),&c,if phase==Phase::Settled{Some(37)}else{None},100_011).unwrap();}
        let before=inventory(&f.path);let view=read(&f,&g,100_012);let accounting=view.accounting.unwrap();assert_eq!(accounting.unknown_attempts,1);assert_eq!(accounting.model_calls_used,1);assert_eq!(accounting.model_calls_remaining,2);assert_eq!(accounting.output_bytes_charged,if phase==Phase::Settled{37}else{2048});assert!(!view.attempts[0].outcome_known&& !view.goal_complete);assert_eq!(view.attempts[0].evidence[0].status,EvidenceStatus::Missing);assert_eq!(inventory(&f.path),before);
    }
}
#[test]fn genuine_model_receipt_is_verified_but_missing_or_forged_receipt_stays_unknown_without_repairs(){
    let(f,a,g,_p,o,_main)=setup("ollama");let c=call("original-response");let row=&g.admissions[0];let proof=row.proof.as_ref().unwrap();a.reserve_attempt(&row.spec,proof,o.lease(),&c,100_009).unwrap();a.start_attempt(&row.spec,proof,o.lease(),&c,100_010).unwrap();a.finish_attempt(&row.spec,proof,o.lease(),&c,Some(37),100_011).unwrap();let stored=a.result_attempt(&row.spec,proof,&c.request_id).unwrap().1.unwrap();let receipt=a.seal_result(&row.spec,proof,o.lease(),&stored,"Free synthetic response",37,100_012).unwrap();super::results::publish(&a,&row.spec,proof,&receipt).unwrap();
    let before=inventory(&f.path);let view=read(&f,&g,100_013);assert!(view.attempts[0].outcome_known);assert_eq!(view.accounting.as_ref().unwrap().unknown_attempts,0);assert!(!view.goal_complete&&!view.criteria_verified);assert_eq!(inventory(&f.path),before);
    let path=f.path.join("pet-runtime-results-v1").join(&row.spec.decision_id).join(format!("{}.json",c.id));let mut forged:serde_json::Value=serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();forged["body"]["text"]="forged".into();fs::write(&path,serde_json::to_vec(&forged).unwrap()).unwrap();let before=inventory(&f.path);let invalid=read(&f,&g,100_014);assert!(!invalid.scan_complete&&!invalid.attempts[0].outcome_known);assert_eq!(invalid.attempts[0].evidence[0].status,EvidenceStatus::Invalid);assert_eq!(invalid.accounting.as_ref().unwrap().output_bytes_charged,37);assert_eq!(inventory(&f.path),before);
    fs::remove_file(&path).unwrap();let before=inventory(&f.path);let missing=read(&f,&g,100_015);assert_eq!(missing.accounting.as_ref().unwrap().unknown_attempts,1);assert_eq!(missing.attempts[0].evidence[0].status,EvidenceStatus::Missing);assert_eq!(inventory(&f.path),before);
}
#[test]fn partial_claim_and_stop_projection_are_observed_without_publishing_a_controller_or_control_event(){
    let f=Fixture::new();let a=Authority::ensure(&root(&f)).unwrap();let g=queued(&f,&f.goal("ollama"),&a);let main=Chat::persistent(f.path.join("live.json"));let c=Controller::new().unwrap();let p=c.prepare(&g,&root(&f),&f.path.join("contexts"),&main,&evidence(&g,100_006),"partial-claim".into(),100_006,Arc::new(|_,_,_|Validity::Current)).unwrap();let mut store=f.store();store.fault=Fault::BeforePublish;assert!(p.claim(&store,&a,&evidence(&g,100_007),100_007).is_err());let before=inventory(&f.path);let view=read(&f,&g,100_008);assert!(!view.source_consistent);let grant=view.grant.unwrap();assert!(!grant.goal_lease_matches&&!grant.control_projection_current);assert_eq!(grant.phase,"claimed");assert_eq!(inventory(&f.path),before);
    let(f,a,g,_p,_o,_main)=setup("codex");let row=&g.admissions[0];a.request_stop(&row.spec,row.proof.as_ref().unwrap(),super::leases::StopReason::Cancel,100_008).unwrap();let before=inventory(&f.path);let view=read(&f,&g,100_009);assert!(view.source_consistent);let grant=view.grant.unwrap();assert_eq!(grant.phase,"draining");assert!(!grant.control_projection_current);assert_eq!(inventory(&f.path),before);
}
#[test]fn wrong_pet_revision_profile_forged_grant_and_ledger_contention_do_not_mutate_sources(){
    let(f,_a,g,_p,_o,_main)=setup("ollama");let before=inventory(&f.path);assert!(f.store().reconciliation(&root(&f),&g.id,"agent_codex",&g.revision,100_008).is_err());assert!(f.store().reconciliation(&root(&f),&g.id,"ai_ollama",&nonce().unwrap(),100_008).is_err());assert!(f.store().reconciliation(&f.path.join("missing"),&g.id,"ai_ollama",&g.revision,100_008).is_err());assert_eq!(inventory(&f.path),before);
    let lock=OpenOptions::new().read(true).write(true).open(root(&f).join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)},0);assert_eq!(f.store().reconciliation(&root(&f),&g.id,"ai_ollama",&g.revision,100_008).err(),Some(model::Error::Busy));assert_eq!(inventory(&f.path),before);drop(lock);
    let path=root(&f).join(format!("{}.json",g.admissions[0].spec.decision_id));let mut grant:serde_json::Value=serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();grant["body"]["phase"]="revoked".into();fs::write(&path,serde_json::to_vec(&grant).unwrap()).unwrap();let before=inventory(&f.path);assert_eq!(f.store().reconciliation(&root(&f),&g.id,"ai_ollama",&g.revision,100_009).err(),Some(model::Error::Conflict));assert_eq!(inventory(&f.path),before);
    let input=serde_json::json!({"petId":"ai_ollama","goalId":g.id,"revision":g.revision,"approve":true,"ownerAbsent":true});assert!(serde_json::from_value::<super::ReconcileInput>(input).is_err());assert_eq!(Failure::Invalid.control_error(),model::Error::Conflict);
}
